old = """        } else { // other exception
            mp_obj_print_exception(&mp_plat_print, MP_OBJ_FROM_PTR(nlr.ret_val));"""
new = """        } else { // other exception
            // pygram: to STDERR, not stdout.
            //
            // Upstream prints an uncaught traceback on stdout, which puts it in
            // the middle of a shell pipeline's data. docs/PYGRAM-SUBSET.md §6
            // makes the opposite contractual: "uncaught exception -> 1 with a
            // traceback on stderr and nothing extra on stdout". This is the
            // single largest source of stdout divergence from CPython, because
            // it corrupts the output of EVERY failing program, not just the
            // error text. MICROPY_ERROR_PRINTER is &mp_stderr_print in this
            // port, and the SystemExit branch above already uses it.
            mp_obj_print_exception(MICROPY_ERROR_PRINTER, MP_OBJ_FROM_PTR(nlr.ret_val));"""
